1	`include "define.v"
2	
3	// 【LSQ Phase2+3 → SRAM 宏化】数据 cache: 对齐 8B line 直映 + 1RW 同步读宏。
4	//
5	// line 模型动机(Phase2+3 保留): entry = 对齐 8B line(index=addr[3+IW-1:3],
6	// tag=高位)。旧 byte-window 模型按访问起始地址匹配, 短步进访问互踢,
7	// CoreMark 实测 dcache load miss 47.6% 且容量加大零收益。
8	//
9	// SRAM 化(2026-07-08):
10	// - {tag,data} 拼宽存进 1RW 同步读宏 Sram4096x113(bit-write-mask 变体), 位段
11	//   {tag[112:64], data[63:0]}; valid 保留 4096b 平铺 FF——宏内容无复位,
12	//   全清/失效语义由 FF 承担。
13	// - 读口协议(单口两拍): lookup_en_i+lookup_addr_i 发射拍读宏, 次拍
14	//   lookup_hit_o/lookup_line_o 针对锁存请求有效。原 req/walk 两个组合读视图
15	//   由桥按 FSM 状态互斥合并到该口({S_IDLE,S_RESP}∩{S_WALK_R,S_AD_UPDATE}=∅,
16	//   证明见 design/specs/ooo-mem-axi-bridge-fsm.md)。
17	// - 窗口移位与跨线阻断移到桥判决拍(统一用锁存 paddr 低 3 位), 本模块只回
18	//   原始 line; req_cacheable_o/req_line_cross_o/walk_cacheable_o 保持纯地址
19	//   0-cycle 组合(不查存储阵列)。
20	//
21	// store 维护(2026-07-09 二期赎回 write-update, 一期无条件失效废止):
22	// - store_rmw_en_i=1(真 store commit): 2 拍 RMW 线内字节合并——
23	//   commit 拍(桥 S_WRITE_REQ 解耦/S_WRITE_RESP b-ok, 该拍宏读口空闲)占宏口
24	//   发读 st_idx 并锁存 store 上下文(idx/tag/line 掩码/line 数据);
25	//   次拍(判决拍, rmw_busy_o=1, 桥压 req_ready 产生 store 后 1 bubble)判
26	//   valid && tag match: 命中则以 wmask 只写 line 内被 store 覆盖的 data 字节
27	//   (tag 段掩码恒 0——store 不写 tag, tag match 才写 data), miss 无动作
28	//   (write-no-allocate)。跨线 store 的下一行(p1)仍无条件清 valid(跨线 RMW
29	//   不做, 保守失效); 本行照常线内合并(line 掩码=wstrb<<off 截断即线内字节)。
30	// - store_rmw_en_i=0(HW A/D PTE 写回维护路): 保持无条件失效(清 valid, 不读
31	//   不写宏, 0 额外拍)——该拍 S_AD_UPDATE 的 read 续访问可能同拍发 lookup,
32	//   宏读口不空闲, 且 PTE 行保热无收益。
33	// - fill 是全行写(全 1 掩码), 桥保证 fill(S_READ_DATA)与 lookup 发射拍/RMW
34	//   两拍窗口状态互斥; 宏口占用者两两同拍视为 1RW 违约(OOO_ASSERT 把关)。
35	module OooDataWordCache #(
36	  // 深度/宽度与 Sram4096x113 定死(4096 项=INDEX_W 12, tag 49b+data 64b=113b),
37	  // 参数仅作文档化, 改值必须换宏(OOO_ASSERT 有 elaboration 检查)。
38	  parameter INDEX_W = `OOO_DATA_WORD_CACHE_INDEX_W,
39	  parameter ENTRY_COUNT = (1 << INDEX_W)
40	) (
41	  input clk,
42	  input rst,
43	
44	  // ---- 纯地址 0-cycle 组合视图(桥 accept 拍决策用, 不查存储阵列) ----
45	  input [`XLEN-1:0] req_lookup_addr_i,
46	  // 本访问的字节窗口宽度(桥侧 wstrb popcount)
47	  input [3:0] req_nbytes_i,
48	  output req_cacheable_o,
49	  output req_line_cross_o,
50	
51	  input [`XLEN-1:0] walk_lookup_addr_i,
52	  output walk_cacheable_o,
53	
54	  // ---- 单读口两拍协议 ----
55	  input lookup_en_i,
56	  input [`XLEN-1:0] lookup_addr_i,
57	  output lookup_hit_o,               // 次拍有效: 锁存地址 cacheable+valid+tag 命中
58	  output [`XLEN-1:0] lookup_line_o,  // 次拍有效: 原始 line(窗口移位归桥判决拍)
59	
60	  input fill_valid_i,
61	  input [`XLEN-1:0] fill_addr_i,   // 须 8B 对齐(桥保证)
62	  input [`XLEN-1:0] fill_data_i,   // 对齐 line 数据
63	
64	  // ---- store 维护 ----
65	  input store_commit_i,
66	  // 1=真 store commit(2 拍 RMW write-update); 0=A/D PTE 写回维护(无条件失效)
67	  input store_rmw_en_i,
68	  input [`XLEN-1:0] store_addr_i,
69	  input [`XLEN-1:0] store_wdata_i,   // 窗口数据(低位起, 与 wstrb 位对齐)
70	  input [`STRB_W-1:0] store_wstrb_i,
71	  // RMW 判决拍占用宏口: 桥须在该拍压 req_ready/不发 lookup(store 后 1 bubble)
72	  output rmw_busy_o
73	);
74	
75	  localparam TAG_W = `XLEN - 3 - INDEX_W;
76	
77	  reg [ENTRY_COUNT-1:0] valid_q;
78	
79	  function [INDEX_W-1:0] line_index;
80	    input [`XLEN-1:0] addr;
81	    begin
82	      line_index = addr[INDEX_W+2:3];
83	    end
84	  endfunction
85	
86	  function [TAG_W-1:0] line_tag;
87	    input [`XLEN-1:0] addr;
88	    begin
89	      line_tag = addr[`XLEN-1:INDEX_W+3];
90	    end
91	  endfunction
92	
93	  function cacheable_addr;
94	    input [`XLEN-1:0] addr;
95	    begin
96	      cacheable_addr = ((addr & `NPC_AXI_PMEM_MASK) == `NPC_AXI_PMEM_BASE);
97	    end
98	  endfunction
99	
100	  function [3:0] nbytes_from_wstrb;
101	    input [`STRB_W-1:0] wstrb;
102	    integer nb_i;
103	    begin
104	      nbytes_from_wstrb = 4'd0;
105	      for (nb_i = 0; nb_i < `STRB_W; nb_i = nb_i + 1)
106	        if (wstrb[nb_i])
107	          nbytes_from_wstrb = nbytes_from_wstrb + 4'd1;
108	      if (nbytes_from_wstrb == 4'd0)
109	        nbytes_from_wstrb = 4'd1;
110	    end
111	  endfunction
112	
113	  // 字节使能 → 位掩码展开(RMW 判决拍的 data 段 wmask)
114	  function [`XLEN-1:0] expand_bytemask;
115	    input [`STRB_W-1:0] mask;
116	    begin
117	      expand_bytemask = {
118	          {8{mask[7]}}, {8{mask[6]}}, {8{mask[5]}}, {8{mask[4]}},
119	          {8{mask[3]}}, {8{mask[2]}}, {8{mask[1]}}, {8{mask[0]}}
120	      };
121	    end
122	  endfunction
123	
124	  // ---- 纯地址组合视图 ----
125	  assign req_cacheable_o = cacheable_addr(req_lookup_addr_i);
126	  assign req_line_cross_o =
127	      ({1'b0, req_lookup_addr_i[2:0]} + req_nbytes_i) > 5'd8;
128	  assign walk_cacheable_o = cacheable_addr(walk_lookup_addr_i);
129	
130	  // ---- store 地址派生(RMW/失效共用) ----
131	  wire [2:0] st_off_w = store_addr_i[2:0];
132	  wire [3:0] st_nbytes_w = nbytes_from_wstrb(store_wstrb_i);
133	  wire st_cross_w = ({1'b0, st_off_w} + st_nbytes_w) > 5'd8;
134	  wire [INDEX_W-1:0] st_idx_w = line_index(store_addr_i);
135	  wire [INDEX_W-1:0] st_idx_p1_w = st_idx_w + {{(INDEX_W-1){1'b0}}, 1'b1};
136	  wire st_cacheable_w = cacheable_addr(store_addr_i);
137	  // line 视角的合并掩码/数据(窗口左移 off 字节; 8b 截断天然只留线内字节,
138	  // 跨线溢出部分由 p1 保守失效兜底)
139	  wire [`STRB_W-1:0] st_line_mask_w = store_wstrb_i << st_off_w;
140	  wire [`XLEN-1:0] st_line_data_w = store_wdata_i << {st_off_w, 3'b000};
141	
142	  // ---- store RMW 2 拍机构 ----
143	  // commit 拍(发射): 占宏口读 st_idx, 同拍锁存 store 上下文。
144	  wire rmw_start_w = store_commit_i && store_rmw_en_i && st_cacheable_w;
145	
146	  reg rmw_pending_q;
147	  reg [INDEX_W-1:0] rmw_idx_q;
148	  reg [TAG_W-1:0] rmw_tag_q;
149	  reg [`STRB_W-1:0] rmw_line_mask_q;
150	  reg [`XLEN-1:0] rmw_line_data_q;
151	
152	  always @(posedge clk) begin
153	    if (rst) begin
154	      rmw_pending_q <= 1'b0;
155	    end else begin
156	      rmw_pending_q <= rmw_start_w;
157	    end
158	    if (rmw_start_w) begin
159	      rmw_idx_q <= st_idx_w;
160	      rmw_tag_q <= line_tag(store_addr_i);
161	      rmw_line_mask_q <= st_line_mask_w;
162	      rmw_line_data_q <= st_line_data_w;
163	    end
164	  end
165	
166	  assign rmw_busy_o = rmw_pending_q;
167	
168	  // ---- 1RW 同步读宏(bit-write-mask): 四占用者状态互斥(桥 FSM 保证) ----
169	  //   lookup 读(发射拍) / fill 全行写 / RMW 读(store commit 拍) / RMW 写(判决拍)
170	  wire fill_we_w = fill_valid_i && cacheable_addr(fill_addr_i);
171	  wire [INDEX_W-1:0] fill_idx_w = line_index(fill_addr_i);
172	  wire [INDEX_W-1:0] lookup_idx_w = line_index(lookup_addr_i);
173	  wire [TAG_W+`XLEN-1:0] sram_rdata_w;
174	
175	  // RMW 判决: 锁存 tag 与宏读出 tag 段比较, valid 用判决拍 FF 值。
176	  // 命中才写; miss(同 index 异 tag/invalid)无动作=write-no-allocate。
177	  wire rmw_hit_w =
178	      rmw_pending_q && valid_q[rmw_idx_q] &&
179	      (sram_rdata_w[TAG_W+`XLEN-1:`XLEN] == rmw_tag_q);
180	
181	  wire sram_en_w = lookup_en_i || fill_we_w || rmw_start_w || rmw_hit_w;
182	  wire sram_we_w = fill_we_w || rmw_hit_w;
183	  wire [INDEX_W-1:0] sram_addr_w =
184	      fill_we_w   ? fill_idx_w :
185	      rmw_hit_w   ? rmw_idx_q :
186	      rmw_start_w ? st_idx_w : lookup_idx_w;
187	  wire [TAG_W+`XLEN-1:0] sram_wdata_w =
188	      fill_we_w ? {line_tag(fill_addr_i), fill_data_i}
189	                : {{TAG_W{1'b0}}, rmw_line_data_q};
190	  // fill 全行写=全 1 掩码; RMW 写只覆盖 data 段被 store 命中的字节,
191	  // tag 段掩码恒 0(store 不写 tag, tag match 才写 data)。
192	  wire [TAG_W+`XLEN-1:0] sram_wmask_w =
193	      fill_we_w ? {(TAG_W+`XLEN){1'b1}}
194	                : {{TAG_W{1'b0}}, expand_bytemask(rmw_line_mask_q)};
195	
196	  Sram4096x113 u_sram (
197	    .clk(clk),
198	    .en_i(sram_en_w),
199	    .we_i(sram_we_w),
200	    .addr_i(sram_addr_w),
201	    .wdata_i(sram_wdata_w),
202	    .wmask_i(sram_wmask_w),
203	    .rdata_o(sram_rdata_w)
204	  );
205	
206	  // 判决拍上下文(发射拍锁存)。valid 用判决拍的 FF 值: 发射拍同沿的 store
207	  // 失效在判决拍已可见, 只会把 hit 保守判成 miss(走 AXI 取新值), 无正确性洞。
208	  reg lookup_pend_q;
209	  reg [INDEX_W-1:0] lookup_idx_q;
210	  reg [TAG_W-1:0] lookup_tag_q;
211	  reg lookup_cacheable_q;
212	
213	  always @(posedge clk) begin
214	    if (rst) begin
215	      lookup_pend_q <= 1'b0;
216	    end else begin
217	      lookup_pend_q <= lookup_en_i;
218	    end
219	    if (lookup_en_i) begin
220	      lookup_idx_q <= lookup_idx_w;
221	      lookup_tag_q <= line_tag(lookup_addr_i);
222	      lookup_cacheable_q <= cacheable_addr(lookup_addr_i);
223	    end
224	  end
225	
226	  assign lookup_hit_o =
227	      lookup_pend_q && lookup_cacheable_q && valid_q[lookup_idx_q] &&
228	      (sram_rdata_w[TAG_W+`XLEN-1:`XLEN] == lookup_tag_q);
229	  assign lookup_line_o = sram_rdata_w[`XLEN-1:0];
230	
231	  // ---- valid FF 维护 ----
232	  //   fill 置位;
233	  //   store(RMW 路)本行不失效(命中判决拍原地合并, miss 原行继续有效——
234	  //     同 index 异 tag 行不再被误清, 这是 write-update 赎回的主收益);
235	  //   跨线 store 的 p1 行无条件清(跨线 RMW 不做, 保守失效);
236	  //   A/D 维护路(store_rmw_en_i=0)保持一期无条件失效(含跨线 p1)。
237	  always @(posedge clk) begin
238	    if (rst) begin
239	      valid_q <= {ENTRY_COUNT{1'b0}};
240	    end else begin
241	      if (fill_we_w)
242	        valid_q[fill_idx_w] <= 1'b1;
243	      if (store_commit_i && st_cacheable_w) begin
244	        if (!store_rmw_en_i) begin
245	          valid_q[st_idx_w] <= 1'b0;
246	          if (st_cross_w)
247	            valid_q[st_idx_p1_w] <= 1'b0;
248	        end else if (st_cross_w) begin
249	          valid_q[st_idx_p1_w] <= 1'b0;
250	        end
251	      end
252	    end
253	  end
254	
255	`ifdef OOO_ASSERT
256	  initial begin
257	    if (INDEX_W != 12) begin
258	      $error("[DWC-SRAM-GEOM] INDEX_W=%0d 与 Sram4096x113(4096x113)宏不匹配",
259	             INDEX_W);
260	      $fatal;
261	    end
262	  end
263	
264	  // 1RW 合同: 宏口四占用者(lookup 发射/fill 写/RMW 读/RMW 判决拍)两两不得
265	  // 同拍(桥 FSM 状态互斥+req_ready 压制保证)。RMW 判决拍即便 miss 不写,
266	  // 口也已保留(busy), 同拍其他占用一律违约。
267	  always @(posedge clk) begin
268	    if (!rst && (({2'b00, lookup_en_i} + {2'b00, fill_we_w} +
269	                  {2'b00, rmw_start_w} + {2'b00, rmw_pending_q}) > 3'd1)) begin
270	      $error("[DWC-SRAM-1RW] 宏口冲突: lookup=%b fill=%b rmw_rd=%b rmw_wr=%b @%0t",
271	             lookup_en_i, fill_we_w, rmw_start_w, rmw_pending_q, $time);
272	      $fatal;
273	    end
274	  end
275	`endif
276	
277	endmodule
