251	  // HW A/D(Svadu, 对齐 NEMU): 权限 fault 只含真权限(R/W/X、U/S、MXR/SUM)。
252	  // A/D 缺失不再 fault, 改由 walker S_AD_UPDATE 写回 PTE 置位(见 data_ad_update_needed)。
253	  function data_permission_fault;
254	    input [`XLEN-1:0] pte;
255	    input write_access;
256	    input [1:0] priv_mode;
257	    input [`XLEN-1:0] status;
258	    begin
259	      data_permission_fault =
260	          (write_access ? !pte[2] : !data_read_ok(pte, status)) ||
261	          !data_user_ok(pte, priv_mode, status);
262	    end
263	  endfunction
