265	  // A/D 需 HW 更新: 真权限已过但 A=0(任意访问)或 D=0(store)。
266	  function data_ad_update_needed;
267	    input [`XLEN-1:0] pte;
268	    input write_access;
269	    begin
270	      data_ad_update_needed = !pte[6] || (write_access && !pte[7]);
271	    end
