560	  // 【SRAM 同步读】read miss 的 AR 从 fire 拍推迟到 S_LOOKUP 判决拍(晚 1 拍),
561	  // 地址/strb 统一取锁存 paddr_q/wstrb_q, 原 req_* 直通支路随之删除。
562	  // S_LOOKUP 项的 !rmw_busy 与 FSM 转移侧一致(读口互斥安全网, 状态互斥下恒真)。
563	  assign lsu_axi_arvalid_o =
564	      !cpu_kill_w &&
565	      (((state_q == S_WALK_AR) && !walk_pte_pmp_fault_w) ||
566	       (state_q == S_READ_ADDR) ||
567	       ((state_q == S_LOOKUP) && !dcache_lookup_hit_final_w &&
568	        !dcache_rmw_busy_w));
569	  wire [`XLEN-1:0] pend_read_araddr_w =
570	      read_cross_q ? paddr_q : {paddr_q[`XLEN-1:3], 3'b000};
571	  assign lsu_axi_araddr_o =
572	      (state_q == S_WALK_AR) ? walk_pte_addr_w : pend_read_araddr_w;
573	  assign lsu_axi_arstrb_o =
574	      (state_q == S_WALK_AR) ? {`STRB_W{1'b1}} :
575	      (read_cross_q ? wstrb_q : {`STRB_W{1'b1}});
576	  assign lsu_axi_rready_o = (state_q == S_WALK_R) || (state_q == S_READ_DATA);
577	  wire write_drain_w =
578	      drop_rsp_q || (flush_i && (aw_done_q || w_done_q));
579	  // HW A/D: S_AD_UPDATE 复用写通道写回 leaf PTE(awaddr=PTE 地址, wdata=置位 PTE, wstrb=全 8B),
580	  // 写必达(不受 cpu_kill 门控; flush 由 FSM 完成写后 drop, 幂等)。
581	  assign lsu_axi_awvalid_o =
582	      ((state_q == S_WRITE_REQ) && !aw_done_q &&
583	       (!cpu_kill_w || write_drain_w || nokill_q)) ||
584	      ((state_q == S_AD_UPDATE) && !aw_done_q);
585	  assign lsu_axi_awaddr_o =
586	      (state_q == S_AD_UPDATE) ? walk_pte_addr_w : paddr_q;
587	  assign lsu_axi_wvalid_o =
588	      ((state_q == S_WRITE_REQ) && !w_done_q &&
589	       (!cpu_kill_w || write_drain_w || nokill_q)) ||
590	      ((state_q == S_AD_UPDATE) && !w_done_q);
591	  assign lsu_axi_wdata_o = (state_q == S_AD_UPDATE) ? ad_pte_q : wdata_q;
592	  assign lsu_axi_wstrb_o = (state_q == S_AD_UPDATE) ? {`STRB_W{1'b1}} : wstrb_q;
593	  // 解耦 store 的 B 由跟踪器吸收：bpend_q 期间持续拉 bready。S_AD_UPDATE 也收 B。
594	  assign lsu_axi_bready_o =
595	      (state_q == S_WRITE_RESP) || bpend_q || (state_q == S_AD_UPDATE);
596	  // 仅 PMEM store 可提前完成(bresp 恒 OK)；!bpend_q 保证至多一个未收 B。
597	  assign store_decouple_w =
598	      ((paddr_q & `NPC_AXI_PMEM_MASK) == `NPC_AXI_PMEM_BASE) && !bpend_q;
599	
600	  // 【刀 M】accept_request 的调用时机从 req fire 拍改为 stage_advance 拍, 全部
601	  // 数据源经 req_*_w 簇取自寄存站(stg_*); 分流决策文本与旧版逐字一致。
602	  task automatic accept_request;
603	    begin
604	      write_q <= req_write_w;
605	      paging_q <= req_translate_w;
606	      access_priv_q <= req_priv_w;
607	      access_svpbmt_en_q <= svpbmt_en_i;
608	      addr_q <= req_addr_w;
609	      paddr_q <= req_cache_addr_w;
610	      read_cross_q <= req_line_cross_w;
611	      wdata_q <= req_wdata_w;
612	      wstrb_q <= req_wstrb_w;
613	      probe_q <= stg_probe_q && req_write_w;
614	      nokill_q <= stg_nokill_q;
615	      rsp_rdata_q <= {`XLEN{1'b0}};
616	      rsp_error_q <= 1'b0;
617	      rsp_page_fault_q <= 1'b0;
618	      aw_done_q <= 1'b0;
619	      w_done_q <= 1'b0;
620	      if (req_data_pmp_fault_w) begin
621	        rsp_error_q <= 1'b1;
622	        rsp_page_fault_q <= 1'b0;
623	        state_q <= S_RESP;
624	      end else if (req_translate_w && req_dtlb_perm_fault_w) begin
625	        rsp_error_q <= 1'b1;
626	        rsp_page_fault_q <= 1'b1;
627	        state_q <= S_RESP;
628	      end else if (req_translate_w && !req_dtlb_hit_w) begin
629	        if (canonical_sv39(req_addr_w)) begin
630	          walk_level_q <= 2'd2;
631	          walk_ppn_q <= satp_i[43:0];
632	          state_q <= S_WALK_AR;
633	        end else begin
634	          rsp_error_q <= 1'b1;
635	          rsp_page_fault_q <= 1'b1;
636	          state_q <= S_RESP;
637	        end
638	      end else if (req_write_w) begin
639	        if (stg_probe_q) begin
640	          // 【LSQ·SQ 切换】write 探测:翻译+PMP 已过, 不写内存, PA 经 rsp_rdata 回传。
641	          rsp_rdata_q <= req_cache_addr_w;
642	          state_q <= S_RESP;
643	        end else begin
644	          state_q <= S_WRITE_REQ;
645	        end
646	      end else begin
647	        // 【SRAM 同步读】读路径统一经 S_LOOKUP: fire 拍已发 dcache 读
648	        // (req_read_lookup_fire_w, 与本分支条件严格一致), 次拍判决 hit/miss。
649	        state_q <= S_LOOKUP;
650	      end
651	    end
652	  endtask
