654	  always @(posedge clk) begin
655	    if (rst) begin
656	      state_q <= S_IDLE;
657	      write_q <= 1'b0;
658	      paging_q <= 1'b0;
659	      access_priv_q <= `PRIV_M;
660	      access_svpbmt_en_q <= 1'b0;
661	      walk_level_q <= 2'd0;
662	      walk_ppn_q <= 44'd0;
663	      addr_q <= {`XLEN{1'b0}};
664	      paddr_q <= {`XLEN{1'b0}};
665	      ad_pte_q <= {`XLEN{1'b0}};
666	      read_cross_q <= 1'b0;
667	      wdata_q <= {`XLEN{1'b0}};
668	      wstrb_q <= {`STRB_W{1'b0}};
669	      rsp_rdata_q <= {`XLEN{1'b0}};
670	      rsp_error_q <= 1'b0;
671	      rsp_page_fault_q <= 1'b0;
672	      aw_done_q <= 1'b0;
673	      w_done_q <= 1'b0;
674	      drop_rsp_q <= 1'b0;
675	      bpend_q <= 1'b0;
676	      probe_q <= 1'b0;
677	      nokill_q <= 1'b0;
678	    end else begin
679	      // B-drain 跟踪器(状态无关，flush 期间也照常吸收已解耦 store 的 B)
680	      if (bpend_q && lsu_axi_bvalid_i) begin
681	        bpend_q <= 1'b0;
682	      end
683	      // 【刀 M】寄存站项进 FSM(stage_advance 拍)最高优先: 只可能发生在 S_IDLE 或
684	      // S_RESP&&rsp_ready(两态 drop_rsp_q 恒 0、无遗留清理义务, done 位由
685	      // accept_request 清零)。nokill 项经 (!cpu_kill_w||stg_nokill_q) 豁免, flush
686	      // 拍也照常进 FSM(写必达; 此时若在 S_RESP, 被顶替的旧响应本就属被 kill 事务,
687	      // 与旧 flush-drain 臂的丢弃行为一致); 非 nokill 项 flush/drop 拍 advance=0,
688	      // FSM 走下方 drain/正常分支。
689	      if (stage_advance_w) begin
690	        accept_request();
691	      end else if ((flush_i || drop_rsp_q) && !nokill_busy_w) begin
692	      case (state_q)
693	        S_IDLE: begin
694	          state_q <= S_IDLE;
695	          aw_done_q <= 1'b0;
696	          w_done_q <= 1'b0;
697	          drop_rsp_q <= 1'b0;
698	        end
699	
700	        // S_LOOKUP: dcache 读无外部副作用, flush 当拍直接释放。
701	        S_WALK_AR, S_READ_ADDR, S_LOOKUP: begin
702	          state_q <= S_IDLE;
703	          aw_done_q <= 1'b0;
704	          w_done_q <= 1'b0;
705	          drop_rsp_q <= 1'b0;
706	        end
