713	            drop_rsp_q <= 1'b0;
714	          end else if (lsu_axi_rvalid_i) begin
715	            state_q <= S_IDLE;
716	            drop_rsp_q <= 1'b0;
717	          end else begin
718	            drop_rsp_q <= 1'b1;
719	          end
720	          aw_done_q <= 1'b0;
721	          w_done_q <= 1'b0;
722	        end
723	
724	        S_WRITE_REQ: begin
725	          if (aw_done_q || w_done_q || aw_fire_w || w_fire_w || drop_rsp_q) begin
726	            aw_done_q <= aw_done_q || aw_fire_w;
727	            w_done_q <= w_done_q || w_fire_w;
728	            drop_rsp_q <= 1'b1;
729	            state_q <= ((aw_done_q || aw_fire_w) &&
730	                        (w_done_q || w_fire_w)) ? S_WRITE_RESP : S_WRITE_REQ;
731	          end else begin
732	            state_q <= S_IDLE;
733	            aw_done_q <= 1'b0;
734	            w_done_q <= 1'b0;
735	            drop_rsp_q <= 1'b0;
736	          end
737	        end
738	
739	        S_WRITE_RESP: begin
740	          if (lsu_axi_bvalid_i) begin
741	            state_q <= S_IDLE;
742	            aw_done_q <= 1'b0;
743	            w_done_q <= 1'b0;
744	            drop_rsp_q <= 1'b0;
745	          end else begin
746	            drop_rsp_q <= 1'b1;
747	          end
748	        end
