753	          if (w_fire_w) w_done_q <= 1'b1;
754	          if ((aw_done_q || aw_fire_w) && (w_done_q || w_fire_w) &&
755	              lsu_axi_bvalid_i) begin
756	            aw_done_q <= 1'b0;
757	            w_done_q <= 1'b0;
758	            drop_rsp_q <= 1'b0;
759	            state_q <= S_IDLE;
760	          end else begin
761	            drop_rsp_q <= 1'b1;
762	          end
763	        end
764	
765	        S_RESP: begin
766	          state_q <= S_IDLE;
767	          aw_done_q <= 1'b0;
768	          w_done_q <= 1'b0;
769	          drop_rsp_q <= 1'b0;
770	        end
771	
772	        default: begin
773	          state_q <= S_IDLE;
774	          aw_done_q <= 1'b0;
775	          w_done_q <= 1'b0;
776	          drop_rsp_q <= 1'b0;
777	        end
778	      endcase
779	      end else begin
780	      case (state_q)
781	        S_IDLE: begin
782	          // 【刀 M】accept 调用已上提为 stage_advance 最高优先分支, 本臂只清 done 位。
783	          aw_done_q <= 1'b0;
784	          w_done_q <= 1'b0;
785	          drop_rsp_q <= 1'b0;
