791	            rsp_error_q <= 1'b1;
792	            rsp_page_fault_q <= 1'b0;
793	            state_q <= S_RESP;
794	          end else if (lsu_axi_arready_i) begin
795	            state_q <= S_WALK_R;
796	          end
797	        end
