803	              rsp_page_fault_q <= 1'b0;
804	              state_q <= S_RESP;
805	            end else if (pte_invalid(lsu_axi_rdata_i) ||
806	                         pte_reserved_fault(lsu_axi_rdata_i,
807	                                            access_svpbmt_en_q,
808	                                            walk_level_q) ||
809	                         (!pte_leaf(lsu_axi_rdata_i) &&
810	                          (walk_level_q == 2'd0))) begin
811	              rsp_error_q <= 1'b1;
812	              rsp_page_fault_q <= 1'b1;
813	              state_q <= S_RESP;
814	            end else if (pte_leaf(lsu_axi_rdata_i)) begin
815	              if (superpage_misaligned(lsu_axi_rdata_i, walk_level_q) ||
816	                  data_permission_fault(lsu_axi_rdata_i, write_q,
817	                                        access_priv_q, mstatus_i)) begin
818	                rsp_error_q <= 1'b1;
819	                rsp_page_fault_q <= 1'b1;
820	                state_q <= S_RESP;
821	              end else if (walk_leaf_pmp_fault_w) begin
822	                rsp_error_q <= 1'b1;
823	                rsp_page_fault_q <= 1'b0;
824	                state_q <= S_RESP;
825	              end else if (walk_ad_needed_w) begin
826	                // HW A/D: 真权限过但 A/D 不足 → 写回置位 PTE(S_AD_UPDATE), B 后再续访问。
827	                ad_pte_q <= lsu_axi_rdata_i | PTE_A_BIT |
828	                            (write_q ? PTE_D_BIT : {`XLEN{1'b0}});
829	                paddr_q <= walk_leaf_paddr_w;
830	                aw_done_q <= 1'b0;
831	                w_done_q <= 1'b0;
832	                state_q <= S_AD_UPDATE;
833	              end else begin
834	                paddr_q <= walk_leaf_paddr_w;
835	                if (write_q) begin
836	                  if (probe_q) begin
837	                    // 【LSQ·SQ 切换】PTW 完成的 write 探测同样短路:PA 回传, 不写。
838	                    rsp_rdata_q <= walk_leaf_paddr_w;
839	                    rsp_error_q <= 1'b0;
840	                    rsp_page_fault_q <= 1'b0;
841	                    state_q <= S_RESP;
842	                  end else begin
843	                    state_q <= S_WRITE_REQ;
844	                  end
845	                end else begin
846	                  // 【SRAM 同步读】leaf-ok read: 当拍已发 dcache 读
847	                  // (walk_read_lookup_fire_w, addr=walk_leaf_paddr_w), 统一
848	                  // 进 S_LOOKUP 判决——修复旧 walk 组合口无移位无跨线检查
