852	              end
853	            end else begin
854	              walk_ppn_q <= lsu_axi_rdata_i[53:10];
855	              walk_level_q <= walk_level_q - 2'd1;
856	              state_q <= S_WALK_AR;
857	            end
858	          end
859	        end
