866	            rsp_rdata_q <= dcache_lookup_line_w >> {paddr_q[2:0], 3'b000};
867	            rsp_error_q <= 1'b0;
868	            rsp_page_fault_q <= 1'b0;
869	            state_q <= S_RESP;
870	          end else begin
871	            // miss/跨线: 当拍发 AR(arvalid 组合含 S_LOOKUP-miss 项)。转移条件
