877	
878	        S_READ_ADDR: begin
879	          if (lsu_axi_arready_i) begin
880	            state_q <= S_READ_DATA;
881	          end
882	        end
883	
884	        S_READ_DATA: begin
885	          if (lsu_axi_rvalid_i) begin
886	            // 不跨线: AXI 返回对齐 line → CPU 视图右移窗口偏移;
