891	            rsp_page_fault_q <= 1'b0;
892	            state_q <= S_RESP;
893	          end
894	        end
895	
896	        S_WRITE_REQ: begin
897	          if (aw_fire_w) begin
898	            aw_done_q <= 1'b1;
899	          end
900	          if (w_fire_w) begin
901	            w_done_q <= 1'b1;
902	          end
903	          if ((aw_done_q || aw_fire_w) && (w_done_q || w_fire_w)) begin
904	            if (store_decouple_w) begin
905	              // PMEM store：数据已落 PMEM(MEM-I2)，bresp 恒 OK；提前报完成，B 交跟踪器。
