907	              rsp_error_q <= 1'b0;
908	              rsp_page_fault_q <= 1'b0;
909	              bpend_q <= 1'b1;
910	              state_q <= S_RESP;
911	            end else begin
912	              // MMIO/uncacheable：仍等 B 以保精确总线异常。
913	              state_q <= S_WRITE_RESP;
914	            end
915	          end
916	        end
917	
918	        S_WRITE_RESP: begin
919	          if (lsu_axi_bvalid_i) begin
920	            rsp_rdata_q <= {`XLEN{1'b0}};
921	            rsp_error_q <= (lsu_axi_bresp_i != 2'b00);
922	            rsp_page_fault_q <= 1'b0;
923	            state_q <= S_RESP;
924	          end
925	        end
926	
927	        S_AD_UPDATE: begin
928	          // HW A/D 写(AW/W→B): 写成功后 TLB 已填置位 PTE(ad_update_b_ok_w), 续原 leaf 访问决策。
929	          if (aw_fire_w) aw_done_q <= 1'b1;
930	          if (w_fire_w) w_done_q <= 1'b1;
931	          if ((aw_done_q || aw_fire_w) && (w_done_q || w_fire_w) &&
932	              lsu_axi_bvalid_i) begin
933	            aw_done_q <= 1'b0;
934	            w_done_q <= 1'b0;
935	            if (lsu_axi_bresp_i != 2'b00) begin
936	              rsp_error_q <= 1'b1;         // A/D 写总线异常 → access fault
937	              rsp_page_fault_q <= 1'b0;
938	              state_q <= S_RESP;
939	            end else if (write_q) begin
940	              if (probe_q) begin
941	                rsp_rdata_q <= paddr_q;    // probe 短路: 返回 PA(=walk_leaf_paddr)
942	                rsp_error_q <= 1'b0;
943	                rsp_page_fault_q <= 1'b0;
944	                state_q <= S_RESP;
945	              end else begin
946	                state_q <= S_WRITE_REQ;    // 真 store: 续写数据
947	              end
948	            end else begin
949	              // 【SRAM 同步读】续 read: 当拍已发 dcache 读(ad_read_lookup_fire_w,
950	              // addr=paddr_q, 不再依赖 R 通道残留的 lsu_axi_rdata_i), 统一进
951	              // S_LOOKUP 判决。
952	              state_q <= S_LOOKUP;
953	            end
954	          end
955	        end
956	
957	        S_RESP: begin
958	          // 【刀 M】back-to-back accept 已上提为 stage_advance 分支(该分支同时覆盖
959	          // rsp 消费拍), 本臂只处理"rsp 被消费且无寄存站项可进"的回 IDLE。
960	          if (rsp_ready_w) begin
961	            aw_done_q <= 1'b0;
962	            w_done_q <= 1'b0;
963	            state_q <= S_IDLE;
964	          end
965	        end
966	
967	        default: begin
968	          state_q <= S_IDLE;
969	        end
970	      endcase
971	      end
972	    end
973	  end
974	
975	  // 【刀 M】寄存站装载/弹出/flush。fire 优先(fire ⇒ ready ⇒ 空位或本拍 advance
976	  // 腾位, 覆盖写即弹出+重装); flush 拍 ready 含 !flush_i 恒无 fire; nokill 项对
977	  // flush 免疫——可在 flush 拍经 advance 弹出, 或原地存活等待 advance(写必达)。
978	  // payload 在 valid=0 拍留脏(全核 valid-only 惯例, 消费方不得读)。
979	  always @(posedge clk) begin
980	    if (rst) begin
981	      stg_valid_q <= 1'b0;
982	      stg_addr_q <= {`XLEN{1'b0}};
983	      stg_wdata_q <= {`XLEN{1'b0}};
984	      stg_wstrb_q <= {`STRB_W{1'b0}};
985	      stg_write_q <= 1'b0;
986	      stg_probe_q <= 1'b0;
987	      stg_pretrans_q <= 1'b0;
988	      stg_nokill_q <= 1'b0;
989	    end else if (mem0_req_fire_w) begin
990	      stg_valid_q <= 1'b1;
991	      stg_addr_q <= mem0_req_addr_i;
992	      stg_wdata_q <= mem0_req_wdata_i;
993	      stg_wstrb_q <= mem0_req_wstrb_i;
994	      stg_write_q <= mem0_req_write_i;
995	      stg_probe_q <= mem0_req_probe_i;
996	      stg_pretrans_q <= mem0_req_pretrans_i;
997	      stg_nokill_q <= mem0_req_nokill_i;
998	    end else if (stage_advance_w) begin
999	      stg_valid_q <= 1'b0;
1000	    end else if (flush_i && !stg_nokill_q) begin
1001	      stg_valid_q <= 1'b0;
1002	    end
1003	  end
1004	
1005	`ifdef OOO_ASSERT
1006	  // 【store RMW 读口互斥】RMW 判决拍(rmw_busy)宏口被占, 桥侧不得出现任何
1007	  // 会用口的动作: 三源 lookup 发射意图/fill/S_LOOKUP 判决。由 FSM 状态互斥
1008	  // (RMW 判决拍状态∈{S_RESP,S_IDLE})+stage_advance 压制(刀 M 后 req 源随
1009	  // advance 迁移, !rmw_busy 项迁入 stage_advance_w)保证, 违反即门控链被破坏。
1010	  always @(posedge clk) begin
1011	    if (!rst && dcache_rmw_busy_w &&
1012	        (req_read_lookup_fire_w || walk_read_lookup_fire_w ||
1013	         ad_read_lookup_fire_w || dcache_read_fill_valid_w ||
1014	         (state_q == S_LOOKUP))) begin
1015	      $error("[MEM-RMW-PORT] RMW 判决拍出现 lookup/fill/S_LOOKUP: state=%0d req=%b walk=%b ad=%b fill=%b @%0t",
1016	             state_q, req_read_lookup_fire_w, walk_read_lookup_fire_w,
1017	             ad_read_lookup_fire_w, dcache_read_fill_valid_w, $time);
1018	      $fatal;
1019	    end
1020	  end
1021	
1022	  // 【刀 M·寄存站契约断言族】全部立即断言形态(SVA 命中 0 教训)。
1023	  reg assert_stg_valid_r;
1024	  reg assert_fire_r;
1025	  reg assert_nokill_hold_r;
1026	  reg [`XLEN-1:0] assert_stg_addr_r;
1027	  reg [`XLEN-1:0] assert_stg_wdata_r;
1028	  reg [`STRB_W-1:0] assert_stg_wstrb_r;
1029	  reg [3:0] assert_stg_attr_r;
1030	  always @(posedge clk) begin
1031	    if (rst) begin
1032	      assert_stg_valid_r <= 1'b0;
1033	      assert_fire_r <= 1'b0;
1034	      assert_nokill_hold_r <= 1'b0;
1035	    end else begin
1036	      // BRG-NOFIRE-FLUSH: flush 拍不得 fire(ready 含 !flush_i ⟺ 寄存站↔MIQ 双射,
1037	      // MIQ flush 分支是 else-if、flush 拍 push 被忽略)。
1038	      if (mem0_req_fire_w && flush_i) begin
1039	        $error("[BRG-NOFIRE-FLUSH] flush 拍出现 mem0_req fire @%0t", $time);
1040	        $fatal;
1041	      end
1042	      // BRG-ADV-NODROP: advance 只可能发生在 drop_rsp_q=0 的拍
1043	      // (S_IDLE/S_RESP 态 drop 恒 0 的 FSM 不变量, 上提 accept 分支依赖它)。
1044	      if (stage_advance_w && drop_rsp_q) begin
1045	        $error("[BRG-ADV-NODROP] drop_rsp_q=1 拍出现 stage_advance @%0t", $time);
1046	        $fatal;
1047	      end
1048	      // BRG-STG-LOOKUP: req 源 dcache lookup 只允许出现在 stage_advance 拍
1049	      // (fire 拍恒 0——旧"fire 拍发 lookup"路径已被寄存站切断)。
1050	      if (req_read_lookup_fire_w && !stage_advance_w) begin
1051	        $error("[BRG-STG-LOOKUP] 非 advance 拍出现 req 源 dcache lookup @%0t",
1052	               $time);
1053	        $fatal;
1054	      end
1055	      // BRG-STG-HOLD: 上拍占用且未重装(fire), 本拍仍占用 ⇒ 字段冻结(PSR-HOLD 型)。
1056	      if (assert_stg_valid_r && !assert_fire_r && stg_valid_q &&
1057	          ((stg_addr_q != assert_stg_addr_r) ||
1058	           (stg_wdata_q != assert_stg_wdata_r) ||
1059	           (stg_wstrb_q != assert_stg_wstrb_r) ||
1060	           ({stg_write_q, stg_probe_q, stg_pretrans_q, stg_nokill_q} !=
1061	            assert_stg_attr_r))) begin
1062	        $error("[BRG-STG-HOLD] stall 拍寄存站字段被改写 @%0t", $time);
1063	        $fatal;
1064	      end
1065	      // BRG-STG-NOKILL: flush 拍未 advance 的 nokill 项次拍必须存活(写必达)。
1066	      if (assert_nokill_hold_r && !stg_valid_q) begin
1067	        $error("[BRG-STG-NOKILL] flush 拍 nokill 寄存站项被丢弃 @%0t", $time);
1068	        $fatal;
1069	      end
1070	      assert_stg_valid_r <= stg_valid_q;
1071	      assert_fire_r <= mem0_req_fire_w;
1072	      assert_nokill_hold_r <= flush_i && stg_valid_q && stg_nokill_q &&
1073	                              !stage_advance_w;
1074	      assert_stg_addr_r <= stg_addr_q;
1075	      assert_stg_wdata_r <= stg_wdata_q;
1076	      assert_stg_wstrb_r <= stg_wstrb_q;
1077	      assert_stg_attr_r <= {stg_write_q, stg_probe_q, stg_pretrans_q,
1078	                            stg_nokill_q};
1079	    end
1080	  end
1081	`endif
1082	
1083	endmodule
