1062	  wire [3:0] issue0_acc_bytes_w =
1063	      4'd1 << issue0_ctrl_w[`CTRL_MEM_SIZE_MSB:`CTRL_MEM_SIZE_LSB];
1064	  wire [3:0] issue1_acc_bytes_w =
1065	      4'd1 << issue1_ctrl_w[`CTRL_MEM_SIZE_MSB:`CTRL_MEM_SIZE_LSB];
