1080	      (issue0_is_amo_w && issue0_mem_misaligned_w) || issue0_xpage_misalign_w;
1081	  wire issue1_mem_exception_w =
1082	      (issue1_is_amo_w && issue1_mem_misaligned_w) || issue1_xpage_misalign_w;
1083	  // MMIO(非 PMEM)load 保守独占: 设备读有副作用, 多在飞会乱设备序。
1084	  wire issue0_mem_mmio_w =
1085	      !((issue0_mem_addr_w & `NPC_AXI_PMEM_MASK) == `NPC_AXI_PMEM_BASE);
1086	  wire issue1_mem_mmio_w =
1087	      !((issue1_mem_addr_w & `NPC_AXI_PMEM_MASK) == `NPC_AXI_PMEM_BASE);
1088	  wire issue_block_w =
1089	      checkpoint_capture_i || checkpoint_quiesce_i;
1090	  // rsp 归属 = MIQ 队头。LEGACY 头沿旧 mem_pending_q 语义; plain 头按 kind 分派。
1091	  wire miq_head_load_w = miq_head_valid_w && (miq_head_kind_w == MIQ_KIND_LOAD);
1092	  wire miq_head_probe_w = miq_head_valid_w && (miq_head_kind_w == MIQ_KIND_PROBE);
1093	  wire miq_head_drain_w = miq_head_valid_w && (miq_head_kind_w == MIQ_KIND_DRAIN);
1094	  wire miq_head_legacy_w = miq_head_valid_w && (miq_head_kind_w == MIQ_KIND_LEGACY);
1095	  // 旧 wants 语义收窄到 LEGACY(AMO/LR/SC/MMIO 独占族)
1096	  wire mem_rsp_wants_w = miq_head_legacy_w && mem_pending_q &&
1097	                         mem_rsp_valid_i && !flush_i;
1098	  // plain LOAD: killed 恒收(静默弃); 活 load 需 wb 槽。PROBE: fault 需 wb 槽,
1099	  // 正常 fill 不占 wb。DRAIN: 恒收(nokill, flush 拍也送达)。
1100	  wire miq_load_rsp_wants_w = miq_head_load_w && mem_rsp_valid_i;
1101	  wire miq_probe_rsp_wants_w = miq_head_probe_w && mem_rsp_valid_i;
1102	  wire miq_drain_rsp_wants_w = miq_head_drain_w && mem_rsp_valid_i;
1103	  wire mem_rsp_fault_w = mem_rsp_error_i || mem_rsp_page_fault_i;
1104	  assign mem_idle_o =
1105	      miq_empty_w && !mem_pending_q && !mem_buffer_valid_q;
1106	  // 【LSQ·SQ 切换】退休侧静默: SQ 排空且无 drain 在飞。AND 进 backend_drained,
1107	  // system/trap/FP 等串行点等它(mem_idle_o 保持原语义, 供分支恢复 quiet 判定)。
1108	  assign mem_retire_quiet_o =
1109	      !sq_mode_w || (sq_empty_w && !drain_inflight_q);
1110	  // 【级间边界治理 P1】EX→WB 级间寄存簇提取为 PipeStageReg 实例
1111	  // (spec: design/arch/pipeline-stage-boundary.md §4 P1——全核唯一真实 stage 寄存簇)。
1112	  // payload 位段布局(144b/lane, 两 lane 一致; rob4+pdest6+result64+exc1+cause5+tval64):
1113	  //   {rob_idx[143:140], pdest[139:134], result[133:70],
1114	  //    exception[69], cause[68:64], tval[63:0]}
1115	  // up_valid/up_payload 由原 always 各赋值臂等价改写的组合逻辑生成(assign 在原
1116	  // always 块位置, 见后文; 声明前置——iverilog 14 拒绝前向引用)。
1117	  wire ex0_up_valid_w;
1118	  wire [143:0] ex0_up_payload_w;
1119	  wire ex0_up_ready_unused_w;
1120	  wire [143:0] ex0_down_payload_w;
1121	  wire ex0_valid_q;
1122	  wire ex1_up_valid_w;
1123	  wire [143:0] ex1_up_payload_w;
1124	  wire ex1_up_ready_unused_w;
1125	  wire [143:0] ex1_down_payload_w;
1126	  wire ex1_valid_q;
1127	
1128	  PipeStageReg #(.WIDTH(144)) u_ex0_stage (
1129	    .clk(clk),
1130	    .rst(rst),
1131	    // flush: 等价于原 flush 臂 rst||flush_i||checkpoint_restore_i(rst 原语内部已处理)
1132	    .flush_i(flush_i || checkpoint_restore_i),
1133	    // kill: 现状契约 = ROB-walk kill 不清 EX→WB 级, 晚到 wb 由 ROB squash 吞(spec §3⑥/§4 P1)
1134	    .kill_i(1'b0),
1135	    .up_valid_i(ex0_up_valid_w),
1136	    // up_ready: down_ready 恒 1 → up_ready 恒 1, 上游 issue 无反压消费点(现状语义)
1137	    .up_ready_o(ex0_up_ready_unused_w),
1138	    .up_payload_i(ex0_up_payload_w),
1139	    .down_valid_o(ex0_valid_q),
1140	    // down_ready: ROB wb 口恒收(ex_q 最高优先、单拍必消费)的现状语义; 未来 wb 仲裁引入反压再改
1141	    .down_ready_i(1'b1),
1142	    .down_payload_o(ex0_down_payload_w)
1143	  );
1144	  PipeStageReg #(.WIDTH(144)) u_ex1_stage (
1145	    .clk(clk),
1146	    .rst(rst),
1147	    // flush: 等价于原 flush 臂 rst||flush_i||checkpoint_restore_i(rst 原语内部已处理)
1148	    .flush_i(flush_i || checkpoint_restore_i),
1149	    // kill: 现状契约 = ROB-walk kill 不清 EX→WB 级, 晚到 wb 由 ROB squash 吞(spec §3⑥/§4 P1)
1150	    .kill_i(1'b0),
1151	    .up_valid_i(ex1_up_valid_w),
1152	    // up_ready: down_ready 恒 1 → up_ready 恒 1, 上游 issue 无反压消费点(现状语义)
1153	    .up_ready_o(ex1_up_ready_unused_w),
1154	    .up_payload_i(ex1_up_payload_w),
1155	    .down_valid_o(ex1_valid_q),
1156	    // down_ready: ROB wb 口恒收(ex_q 最高优先、单拍必消费)的现状语义; 未来 wb 仲裁引入反压再改
1157	    .down_ready_i(1'b1),
1158	    .down_payload_o(ex1_down_payload_w)
1159	  );
1160	
1161	  // _q 别名: 语义仍是寄存器输出(寄存器在 PipeStageReg 内), 下游 wb mux 读点零文本改动;
1162	  // 提取见 design/arch/pipeline-stage-boundary.md P1。payload 仅 exN_valid_q=1 拍有效
1163	  // (flush/未装载拍留脏——全核 valid-only 惯例, 消费方不得在 valid=0 时读)。
1164	  wire [ROB_INDEX_W-1:0] ex0_rob_idx_q = ex0_down_payload_w[143:140];
1165	  wire [PHY_REG_ADDR_W-1:0] ex0_pdest_q = ex0_down_payload_w[139:134];
1166	  wire [`XLEN-1:0] ex0_result_q = ex0_down_payload_w[133:70];
1167	  wire ex0_exception_q = ex0_down_payload_w[69];
1168	  wire [`TRAP_CAUSE_W-1:0] ex0_cause_q = ex0_down_payload_w[68:64];
1169	  wire [`XLEN-1:0] ex0_tval_q = ex0_down_payload_w[63:0];
1170	  wire [ROB_INDEX_W-1:0] ex1_rob_idx_q = ex1_down_payload_w[143:140];
1171	  wire [PHY_REG_ADDR_W-1:0] ex1_pdest_q = ex1_down_payload_w[139:134];
1172	  wire [`XLEN-1:0] ex1_result_q = ex1_down_payload_w[133:70];
1173	  wire ex1_exception_q = ex1_down_payload_w[69];
1174	  wire [`TRAP_CAUSE_W-1:0] ex1_cause_q = ex1_down_payload_w[68:64];
1175	  wire [`XLEN-1:0] ex1_tval_q = ex1_down_payload_w[63:0];
1176	  wire [1:0] wb_free_count_w =
1177	      {1'b0, !ex0_valid_q} + {1'b0, !ex1_valid_q};
1178	  wire wb_slot_free_w = (wb_free_count_w != 2'b00);
1179	  // ready 按队头 kind: LOAD(killed 恒收/活 load 等 wb 槽); PROBE(正常恒收,
1180	  // fault 等 wb 槽); DRAIN 恒收; LEGACY 沿旧(wants && wb 槽)。
1181	  assign mem_rsp_ready_o =
1182	      miq_head_drain_w ? 1'b1 :
1183	      miq_head_load_w ? (miq_head_killed_w || wb_slot_free_w) :
1184	      miq_head_probe_w ? (miq_head_killed_w || wb_slot_free_w) :
1185	      (mem_rsp_wants_w && wb_slot_free_w);
1186	  // LEGACY 消费 fire(旧路径全部沿用此名)
1187	  wire mem_rsp_fire_w = mem_rsp_wants_w && mem_rsp_ready_o;
1188	  // plain 消费 fire
1189	  wire miq_load_rsp_fire_w = miq_load_rsp_wants_w && mem_rsp_ready_o;
1190	  wire miq_probe_rsp_fire_w = miq_probe_rsp_wants_w && mem_rsp_ready_o;
1191	  wire miq_drain_rsp_fire_w = miq_drain_rsp_wants_w;
1192	  // 队头出队: 任一类消费完成。AMO 读阶段(amo_read_rsp)也出队——AMO 写请求
1193	  // 发射时再 push 一个新 LEGACY entry(读/写两事务两 entry, 序天然正确)。
1194	  assign miq_pop_w = mem_rsp_fire_w || miq_load_rsp_fire_w ||
1195	                     miq_probe_rsp_fire_w || miq_drain_rsp_fire_w;
1196	  // AMO#2: 读阶段若 fault(error/page_fault),不得进入写阶段(否则病态 PMP W&!R 下会静默错写 +
1197	  // rd 垃圾 + 无异常)。fault 时 mem_amo_read_rsp_w=0 → 走 mem_rsp_final_fire_w 经 mem_rsp_wb_cause_w
1198	  // 报 LOAD fault(对齐 NEMU "AMO 先 Mr→Load fault"),且不写内存。常态(无 fault)行为不变。
1199	  wire mem_amo_read_rsp_w =
1200	      mem_rsp_fire_w && mem_amo_q && !mem_amo_lr_q && !mem_amo_sc_q &&
1201	      !mem_amo_write_phase_q &&
1202	      !mem_rsp_error_i && !mem_rsp_page_fault_i;
1203	  wire mem_rsp_final_fire_w = mem_rsp_fire_w && !mem_amo_read_rsp_w;
1204	  // LEGACY 单例空闲(AMO/LR/SC 独占通道)
1205	  wire mem_legacy_slot_open_w = !mem_pending_q || mem_rsp_final_fire_w;
1206	  // plain(LOAD/PROBE)发射: MIQ 有空且 LEGACY 空(AMO 在飞时保守不混发,
1207	  // 保持原子窗口语义与旧版一致)。MIQ 同拍 pop 腾位计入。
1208	  wire miq_slot_open_w = mem_legacy_slot_open_w &&
1209	                         (!miq_full_w || miq_pop_w);
1210	  // AMO/LR/SC 独占: MIQ 必须全空(其读-改-写窗口内无任何 plain 在飞)。
1211	  wire mem_amo_slot_open_w = mem_legacy_slot_open_w &&
1212	                             (miq_empty_w || (miq_pop_w &&
1213	                              (miq_count_w == {{MIQ_ENTRY_W{1'b0}}, 1'b1})));
1214	  // 兼容名: 旧引用点按"发射者是否 AMO 族"细分, 在下方逐点替换。
1215	  wire mem_request_slot_open_w = miq_slot_open_w;
1216	  function [ROB_INDEX_W:0] rob_distance_from_head;
1217	    input [ROB_INDEX_W-1:0] idx;
1218	    input [ROB_INDEX_W-1:0] head;
1219	    begin
1220	      rob_distance_from_head = {1'b0, (idx - head)};
1221	    end
1222	  endfunction
1223	
1224	  function rob_idx_older_than;
1225	    input [ROB_INDEX_W-1:0] older_idx;
1226	    input [ROB_INDEX_W-1:0] younger_idx;
1227	    input [ROB_INDEX_W-1:0] head;
1228	    begin
1229	      rob_idx_older_than =
1230	          rob_distance_from_head(older_idx, head) <
1231	          rob_distance_from_head(younger_idx, head);
1232	    end
1233	  endfunction
1234	
1235	  wire mem_pending_store_order_block_w =
1236	      mem_pending_q && (mem_store_q || mem_amo_q);
1237	  wire mem_buffer_store_order_block_w =
1238	      mem_buffer_valid_q && mem_buffer_store_q;
1239	  // 【LSQ·歧义消解切片(spec Phase2 前半)】load 对更老在飞 store 的等待从 addr-blind
1240	  //   (任何 store 在飞就等)细化为地址重叠判定: 双方 8B line 距离 ≤1(覆盖任一侧跨线
1241	  //   misaligned 的保守窗口)才等, 不重叠即放行——独立 load 不再被无关 store 卡死。
1242	  //   保守保留 blind 等待的场景: AMO/LR/SC(原子语义)与 MMIO/非 PMEM store(设备顺序),
1243	  //   经 mem_pending_amo/mmio 判定; store→load 同址可见性仍由 dcache 精确 per-store
1244	  //   更新(LSQ Step1)+ 重叠即等待保证, 前递(forwarding)属 Phase2 后半未启用。
1245	  function line_overlap_1;
1246	    input [`XLEN-1:0] la;
1247	    input [`XLEN-1:0] sa;
1248	    reg [`XLEN-4:0] ll;
1249	    reg [`XLEN-4:0] sl;
1250	    begin
1251	      ll = la[`XLEN-1:3];
1252	      sl = sa[`XLEN-1:3];
1253	      line_overlap_1 = (ll == sl) ||
1254	                       (ll + {{(`XLEN-4){1'b0}}, 1'b1} == sl) ||
1255	                       (sl + {{(`XLEN-4){1'b0}}, 1'b1} == ll);
1256	    end
1257	  endfunction
1258	  // 非 PMEM(MMIO)store 保守 blind: 与设备写序相关, 不做重叠放行。
1259	  wire mem_pending_store_mmio_w =
1260	      !((mem_eff_addr_q & `NPC_AXI_PMEM_MASK) == `NPC_AXI_PMEM_BASE);
1261	  wire mem_pending_blind_w =
1262	      mem_pending_q && (mem_amo_q || (mem_store_q && mem_pending_store_mmio_w));
1263	  wire mem_buffer_store_mmio_w =
1264	      !((mem_buffer_eff_addr_q & `NPC_AXI_PMEM_MASK) == `NPC_AXI_PMEM_BASE);
1265	  // 【LSQ·SQ 切换】load 对 SQ 中在飞 store(probe 完成、未落存)的等待判定:
1266	  // committed entry 恒视为更老(其 rob_idx 已随退休回收, 不可作环形 age 比较);
1267	  // 未 committed entry 用 rob_idx age(SQ 中可能存在比 load 年轻的 store, 不拦)。
1268	  // 翻译开启时保守 blind(SQ 存 PA、load 只有 VA, VA 别名使 VA 比对不安全);
1269	  // MMIO entry blind(设备访问序); M-mode(VA=PA)用 8B line 重叠精确判定。
1270	  // addr_valid=0 的 entry(probe 未完成)由 IQ older_store_seen + pending/buffer 判定覆盖。
1271	  // issue0/issue1 分两个 always 块: 同块合并会让 Verilator 把"issue1 地址经旁路
1272	  // 依赖 issue0_fire"的单向链误判为组合环(UNOPTFLAT)。
1273	  reg issue0_sq_block_r;
1274	  reg issue1_sq_block_r;
1275	  always @(*) begin : sq_load_block0_blk
1276	    integer k;
1277	    reg [`XLEN-1:0] entry_addr_r;
1278	    reg entry_mmio_r;
1279	    issue0_sq_block_r = 1'b0;
1280	    for (k = 0; k < SQ_ENTRY_N; k = k + 1) begin
1281	      entry_addr_r = sq_snoop_addr_w[k*`XLEN +: `XLEN];
1282	      entry_mmio_r =
1283	          ((entry_addr_r & `NPC_AXI_PMEM_MASK) != `NPC_AXI_PMEM_BASE);
1284	      if (sq_snoop_valid_w[k] && sq_snoop_addr_valid_w[k] &&
1285	          (mem_translate_active_i || entry_mmio_r ||
1286	           line_overlap_1(issue0_mem_addr_w, entry_addr_r)) &&
1287	          (sq_snoop_committed_w[k] ||
1288	           rob_idx_older_than(sq_snoop_rob_idx_w[k*ROB_INDEX_W +: ROB_INDEX_W],
1289	                              issue0_rob_idx_w, rob_head_idx_w)))
1290	        issue0_sq_block_r = 1'b1;
1291	    end
1292	  end
1293	  always @(*) begin : sq_load_block1_blk
1294	    integer k;
1295	    reg [`XLEN-1:0] entry_addr_r;
1296	    reg entry_mmio_r;
1297	    issue1_sq_block_r = 1'b0;
1298	    for (k = 0; k < SQ_ENTRY_N; k = k + 1) begin
1299	      entry_addr_r = sq_snoop_addr_w[k*`XLEN +: `XLEN];
1300	      entry_mmio_r =
1301	          ((entry_addr_r & `NPC_AXI_PMEM_MASK) != `NPC_AXI_PMEM_BASE);
1302	      if (sq_snoop_valid_w[k] && sq_snoop_addr_valid_w[k] &&
1303	          (mem_translate_active_i || entry_mmio_r ||
1304	           line_overlap_1(issue1_mem_addr_w, entry_addr_r)) &&
1305	          (sq_snoop_committed_w[k] ||
1306	           rob_idx_older_than(sq_snoop_rob_idx_w[k*ROB_INDEX_W +: ROB_INDEX_W],
1307	                              issue1_rob_idx_w, rob_head_idx_w)))
1308	        issue1_sq_block_r = 1'b1;
1309	    end

