3	// 【LSQ Phase2+3 第一刀】访存在飞事务顺序队列(spec ooo-lsq-implementation-plan.md §4)。
4	//
5	// 桥响应恒按请求序返回(单 FSM; 后续 slave/xbar 流水化亦保持 in-order), 故
6	// in-flight 事务用顺序 FIFO 承载, rsp 恒配 FIFO 头——无需 AXI ID/乱序 tag,
7	// 且结构性消灭"迟到 rsp 撞号"族(单例寄存器+rob 匹配才会撞, 序配对天然免疫)。
8	//
9	// kind 语义:
10	//   LOAD  = plain load(数据回填 wb/fpld_wb), 可被 ROB-walk kill(killed 置位,
11	//           rsp 到达即静默弃);
12	//   PROBE = plain store 的翻译/PMP 探测(rsp: PA→SQ fill / fault→wb exception);
13	//   DRAIN = SQ 退休落存写(nokill, flush 不清, rsp 仅通知 SQ pop);
14	//   LEGACY= AMO/LR/SC 与 mem_buffer 迁移等旧单例通道事务的占位——状态仍在
15	//           IntBackend 的 mem_*_q 单例(该族发射条件=本队列空, 在飞期间不发新,
16	//           故 LEGACY 在队列中恒独占且深度恒 1, 行为与旧版逐位一致)。
17	//
18	// 发射并发度: LOAD/PROBE/DRAIN 互相可背靠背(队列有空+桥 ready 即发);
19	// LEGACY 独占。这把"每 load 发→等 rsp→再发"的单例串行(访存 ILP 真封顶之一)
20	// 换成 dcache-hit 流 1 load/拍的流水。
21	module OooMemInflightQueue #(
22	  parameter ENTRY_N = 4,
23	  parameter ENTRY_W = 2,
24	  parameter ROB_INDEX_W = `OOO_ROB_INDEX_W,
25	  parameter PHY_REG_ADDR_W = `OOO_PHY_REG_ADDR_W
26	) (
27	  input clk,
28	  input rst,
29	  input flush_i,
30	
31	  // push(发射拍, 与桥 req fire 同拍——【P5 刀 M】fire 语义=进桥侧 req 寄存站,
32	  // 事务从进站起即被记账, 桥内寄存站项↔MIQ 项保持双射)
33	  input push_valid_i,
34	  input [1:0] push_kind_i,
35	  input [ROB_INDEX_W-1:0] push_rob_idx_i,
36	  input [PHY_REG_ADDR_W-1:0] push_pdest_i,
37	  input push_pdest_fp_i,
38	  input [1:0] push_size_i,
39	  input push_unsigned_i,
40	  input [`XLEN-1:0] push_eff_addr_i,
41	  // PROBE 专用: 发射拍寄存的 store 数据/掩码(rsp 拍随 PA 一起回填 SQ)
42	  input [`XLEN-1:0] push_wdata_i,
43	  input [`STRB_W-1:0] push_wstrb_i,
44	
45	  // pop(rsp 消费拍)
46	  input pop_valid_i,
47	
48	  // ROB-walk kill: 比 kill_rob_idx 年轻的 LOAD/PROBE 标 killed
49	  input kill_valid_i,
50	  input [ROB_INDEX_W-1:0] kill_rob_idx_i,
51	  input [ROB_INDEX_W-1:0] rob_head_idx_i,
52	
53	  // 队头视图(rsp 归属)
54	  output head_valid_o,
55	  output [1:0] head_kind_o,
56	  output head_killed_o,
57	  output [ROB_INDEX_W-1:0] head_rob_idx_o,
58	  output [PHY_REG_ADDR_W-1:0] head_pdest_o,
59	  output head_pdest_fp_o,
60	  output [1:0] head_size_o,
61	  output head_unsigned_o,
62	  output [`XLEN-1:0] head_eff_addr_o,
63	  output [`XLEN-1:0] head_wdata_o,
64	  output [`STRB_W-1:0] head_wstrb_o,
65	
66	  // 占用视图(发射决策/序判定)
67	  output [ENTRY_W:0] count_o,
68	  output empty_o,
69	  output full_o,
70	  // 在飞 LOAD/PROBE 中是否存在 store 序相关项(恒 0——LOAD/PROBE 无写副作用;
71	  // 保留口位由 IntBackend 的 LEGACY 单例判定承担)
72	  output [ENTRY_N-1:0] entry_valid_o,
73	  output [ENTRY_N*2-1:0] entry_kind_o,
74	  output [ENTRY_N*ROB_INDEX_W-1:0] entry_rob_idx_o,
75	  output [ENTRY_N*`XLEN-1:0] entry_addr_o
76	);
77	
78	  localparam [1:0] KIND_LOAD = 2'd0;
79	  localparam [1:0] KIND_PROBE = 2'd1;
80	  localparam [1:0] KIND_DRAIN = 2'd2;
81	  localparam [1:0] KIND_LEGACY = 2'd3;
82	  // KIND_LEGACY 仅由父模块比对 head_kind 使用, 本模块内 kill 白名单不含它
83	  wire [1:0] kind_legacy_unused_w = KIND_LEGACY;
84	
85	  reg valid_q [0:ENTRY_N-1];
86	  reg [1:0] kind_q [0:ENTRY_N-1];
87	  reg killed_q [0:ENTRY_N-1];
88	  reg [ROB_INDEX_W-1:0] rob_idx_q [0:ENTRY_N-1];
89	  reg [PHY_REG_ADDR_W-1:0] pdest_q [0:ENTRY_N-1];
90	  reg pdest_fp_q [0:ENTRY_N-1];
91	  reg [1:0] size_q [0:ENTRY_N-1];
92	  reg unsigned_q [0:ENTRY_N-1];
93	  reg [`XLEN-1:0] eff_addr_q [0:ENTRY_N-1];
94	  reg [`XLEN-1:0] wdata_q [0:ENTRY_N-1];
95	  reg [`STRB_W-1:0] wstrb_q [0:ENTRY_N-1];
96	
97	  reg [ENTRY_W-1:0] head_q;
98	  reg [ENTRY_W-1:0] tail_q;
99	  reg [ENTRY_W:0] count_q;
100	
101	  integer i;
102	
103	  assign head_valid_o = (count_q != {(ENTRY_W+1){1'b0}});
104	  assign head_kind_o = kind_q[head_q];
105	  assign head_killed_o = killed_q[head_q];
106	  assign head_rob_idx_o = rob_idx_q[head_q];
107	  assign head_pdest_o = pdest_q[head_q];
108	  assign head_pdest_fp_o = pdest_fp_q[head_q];
109	  assign head_size_o = size_q[head_q];
110	  assign head_unsigned_o = unsigned_q[head_q];
111	  assign head_eff_addr_o = eff_addr_q[head_q];
112	  assign head_wdata_o = wdata_q[head_q];
113	  assign head_wstrb_o = wstrb_q[head_q];
114	
115	  assign count_o = count_q;
116	  assign empty_o = (count_q == {(ENTRY_W+1){1'b0}});
117	  assign full_o = (count_q == ENTRY_N[ENTRY_W:0]);
118	
119	  genvar gi;
120	  generate
121	    for (gi = 0; gi < ENTRY_N; gi = gi + 1) begin : g_snoop
122	      assign entry_valid_o[gi] = valid_q[gi];
123	      assign entry_kind_o[gi*2 +: 2] = kind_q[gi];
124	      assign entry_rob_idx_o[gi*ROB_INDEX_W +: ROB_INDEX_W] = rob_idx_q[gi];
125	      assign entry_addr_o[gi*`XLEN +: `XLEN] = eff_addr_q[gi];
126	    end
127	  endgenerate
128	
129	  // flush 时 DRAIN(nokill 写必达)必须存活: 队列压缩保留 DRAIN——
130	  // 但 DRAIN 与被清事务在桥内的 AXI 序: 桥 cpu_kill 会丢弃非 nokill 在飞
131	  // 事务的响应(drop_rsp), 响应流中被丢事务不再产生 rsp, 压缩后的队列序
132	  // 与存活响应序保持一致(桥按请求序, 丢弃不改变存活者相对序)。
133	  reg [ENTRY_W:0] flush_keep_count_r;
134	  always @(*) begin : flush_count_blk
135	    integer k;
136	    flush_keep_count_r = {(ENTRY_W+1){1'b0}};
137	    for (k = 0; k < ENTRY_N; k = k + 1) begin
138	      if (valid_q[k] && (kind_q[k] == KIND_DRAIN))
139	        flush_keep_count_r = flush_keep_count_r + {{ENTRY_W{1'b0}}, 1'b1};
140	    end
141	  end
142	
143	  wire push_fire_w = push_valid_i && !full_o;
144	  wire pop_fire_w = pop_valid_i && head_valid_o;
145	
146	  always @(posedge clk) begin
147	    if (rst) begin
148	      head_q <= {ENTRY_W{1'b0}};
149	      tail_q <= {ENTRY_W{1'b0}};
150	      count_q <= {(ENTRY_W+1){1'b0}};
151	      for (i = 0; i < ENTRY_N; i = i + 1) begin
152	        valid_q[i] <= 1'b0;
153	        kind_q[i] <= 2'b00;
154	        killed_q[i] <= 1'b0;
155	        rob_idx_q[i] <= {ROB_INDEX_W{1'b0}};
156	        pdest_q[i] <= {PHY_REG_ADDR_W{1'b0}};
157	        pdest_fp_q[i] <= 1'b0;
158	        size_q[i] <= 2'b00;
159	        unsigned_q[i] <= 1'b0;
160	        eff_addr_q[i] <= {`XLEN{1'b0}};
161	        wdata_q[i] <= {`XLEN{1'b0}};
162	        wstrb_q[i] <= {`STRB_W{1'b0}};
163	      end
164	    end else if (flush_i) begin : flush_blk
165	      // 压缩保留 DRAIN(程序序=队列序, 压缩保序)
166	      integer rd;
167	      integer wr;
168	      reg [ENTRY_W-1:0] src;
169	      wr = 0;
170	      for (rd = 0; rd < ENTRY_N; rd = rd + 1) begin
171	        src = head_q + rd[ENTRY_W-1:0];
172	        if ((rd[ENTRY_W:0] < count_q) && valid_q[src] &&
173	            (kind_q[src] == KIND_DRAIN)) begin
174	          kind_q[wr[ENTRY_W-1:0]] <= kind_q[src];
175	          killed_q[wr[ENTRY_W-1:0]] <= 1'b0;
176	          rob_idx_q[wr[ENTRY_W-1:0]] <= rob_idx_q[src];
177	          pdest_q[wr[ENTRY_W-1:0]] <= pdest_q[src];
178	          pdest_fp_q[wr[ENTRY_W-1:0]] <= pdest_fp_q[src];
179	          size_q[wr[ENTRY_W-1:0]] <= size_q[src];
180	          unsigned_q[wr[ENTRY_W-1:0]] <= unsigned_q[src];
181	          eff_addr_q[wr[ENTRY_W-1:0]] <= eff_addr_q[src];
182	          wdata_q[wr[ENTRY_W-1:0]] <= wdata_q[src];
183	          wstrb_q[wr[ENTRY_W-1:0]] <= wstrb_q[src];
184	          wr = wr + 1;
185	        end
186	      end
187	      for (i = 0; i < ENTRY_N; i = i + 1)
188	        valid_q[i] <= (i < wr) ? 1'b1 : 1'b0;
189	      head_q <= {ENTRY_W{1'b0}};
190	      tail_q <= wr[ENTRY_W-1:0];
191	      count_q <= wr[ENTRY_W:0];
192	    end else begin
193	      if (push_fire_w) begin
194	        valid_q[tail_q] <= 1'b1;
195	        kind_q[tail_q] <= push_kind_i;
196	        // 【F2】kill 拍同拍 push 的 entry 也按 age 判杀: mispredict 当拍 IQ squash 尚未
197	        // 生效(寄存一拍), wrong-path load/probe 仍可 issue 并 push——kill 扫描只看
198	        // valid_q 旧值会漏标它, 其迟到 rsp 会写"已被 walk 回收并重分配"的 preg
199	        // (CoreMark p42 污染案, 架构 GPR 对拍不炸、IQ 消费者读脏)。mode=1 恒 kill
200	        // 时代漏标 entry 总被下一次 kill 补标, 免 redirect 后窗口显形。
201	        killed_q[tail_q] <= kill_valid_i &&
202	            ((push_kind_i == KIND_LOAD) || (push_kind_i == KIND_PROBE)) &&
203	            ((push_rob_idx_i - rob_head_idx_i) >
204	             (kill_rob_idx_i - rob_head_idx_i));
205	        rob_idx_q[tail_q] <= push_rob_idx_i;
206	        pdest_q[tail_q] <= push_pdest_i;
207	        pdest_fp_q[tail_q] <= push_pdest_fp_i;
208	        size_q[tail_q] <= push_size_i;
209	        unsigned_q[tail_q] <= push_unsigned_i;
210	        eff_addr_q[tail_q] <= push_eff_addr_i;
211	        wdata_q[tail_q] <= push_wdata_i;
212	        wstrb_q[tail_q] <= push_wstrb_i;
213	        tail_q <= tail_q + {{(ENTRY_W-1){1'b0}}, 1'b1};
214	      end
215	      if (pop_fire_w) begin
216	        valid_q[head_q] <= 1'b0;
217	        head_q <= head_q + {{(ENTRY_W-1){1'b0}}, 1'b1};
218	      end
219	      count_q <= count_q + {{ENTRY_W{1'b0}}, push_fire_w}
220	                         - {{ENTRY_W{1'b0}}, pop_fire_w};
221	      // ROB-walk kill: LOAD/PROBE 且比 kill 点年轻 → killed(rsp 到弃)。
222	      // DRAIN(已退休)/LEGACY(发射条件=独占, kill 语义沿旧 flush 路)不标。
223	      if (kill_valid_i) begin
224	        for (i = 0; i < ENTRY_N; i = i + 1) begin
225	          if (valid_q[i] &&
226	              ((kind_q[i] == KIND_LOAD) || (kind_q[i] == KIND_PROBE)) &&
227	              ((rob_idx_q[i] - rob_head_idx_i) >
228	               (kill_rob_idx_i - rob_head_idx_i))) begin
229	            killed_q[i] <= 1'b1;
230	          end
231	        end
232	      end
233	    end
234	  end
235	
236	endmodule
